    "explicacion": "Los condilomas acuminados suelen asociarse a genotipos de VPH de bajo riesgo oncogénico, especialmente 6 y 11. Entre las opciones terapéuticas para lesiones externas seleccionadas están imiquimod, crioterapia, ácido tricloroacético y métodos escisionales, según localización, extensión, embarazo y preferencias. Ningún tratamiento garantiza eliminar completamente el virus, y las recurrencias son posibles. Las lesiones pigmentadas, induradas, ulceradas, sangrantes o de diagnóstico incierto requieren valoración y posible biopsia.",
    "perlaENARM": "Los condilomas se asocian habitualmente a VPH 6 y 11. La presencia de una lesión atípica o sospechosa obliga a considerar biopsia en vez de asumir que toda lesión exofítica es un condiloma benigno.",
