    "caso": "Mujer de 62 años presenta prurito vulvar crónico, dispareunia y fisuras recurrentes. La exploración muestra placas blanquecinas atróficas en patrón perineal y perianal, con pérdida parcial de la arquitectura de los labios menores. Una pequeña zona presenta engrosamiento focal nuevo respecto a las consultas anteriores.",
