    "caso": "Mujer de 28 años, asintomática, con ciclos regulares. Durante una ecografía pélvica por dolor abdominal ya resuelto se identifica una lesión anexial derecha de 4.1 cm, unilocular, anecoica, de pared fina y lisa, sin septos, papilas ni componentes sólidos. No presenta ascitis y el Doppler no muestra vascularización interna. La prueba de embarazo es negativa.",
