    "explicacion": "El teratoma quístico maduro es un tumor germinal benigno frecuente en mujeres jóvenes. Puede contener grasa, pelo, calcificaciones y otros tejidos derivados de las capas germinales. La presencia de componentes ecogénicos y sombra acústica es característica, aunque el diagnóstico debe integrar toda la morfología. El manejo depende del tamaño, los síntomas, la sospecha de torsión y las características de imagen. Cuando se indica cirugía, se procura preservar tejido ovárico sano si es técnicamente posible. La torsión es una complicación relevante.",
    "perlaENARM": "Mujer joven con masa ovárica que contiene grasa o calcificaciones: considera teratoma quístico maduro. El tamaño y la movilidad de la lesión aumentan la preocupación por torsión.",
