    "explicacion": "En adolescentes y mujeres jóvenes con una masa ovárica sólida o compleja debe considerarse un tumor de células germinales. La alfa-fetoproteína puede elevarse en tumores del saco vitelino y algunos tumores germinales mixtos; la beta-hCG puede elevarse en tumores con diferenciación trofoblástica, y la LDH puede ser útil en disgerminoma. Ningún marcador aislado establece por sí solo la histología. La selección de pruebas debe orientarse por la edad, la imagen y la valoración especializada, evitando retrasar la atención de una masa sospechosa.",
