    "caso": "Mujer de 46 años detecta un nódulo mamario izquierdo de reciente aparición. La mamografía y la ecografía muestran una lesión irregular, de márgenes espiculados, orientación no paralela a la piel y sombra acústica posterior. El informe radiológico la clasifica como BI-RADS 5.",
