    "explicacion": "BI-RADS 5 indica una lesión altamente sospechosa de malignidad y requiere diagnóstico histológico. La biopsia con aguja gruesa permite obtener tejido para establecer el tipo histológico y evaluar biomarcadores relevantes, como receptores hormonales y HER2 cuando se confirma carcinoma. La correlación radiológico-patológica es esencial; si los resultados son discordantes, debe considerarse repetir la biopsia o realizar una evaluación adicional. No es apropiado sustituir la confirmación tisular por tratamiento empírico.",
