    "explicacion": "El carcinoma ductal in situ (CDIS) permanece confinado al sistema ductal y no tiene invasión del estroma por definición. En lesiones localizadas, la cirugía conservadora seguida de radioterapia es una estrategia habitual cuando puede lograrse resección completa con márgenes adecuados. La hormonoterapia puede reducir el riesgo de eventos mamarios en pacientes seleccionadas con receptores hormonales positivos. La mastectomía se considera cuando la extensión, la multicentricidad, la relación tumor-mama o la imposibilidad de administrar radioterapia impiden una conservación adecuada. El alto grado histológico no convierte por sí solo una lesión in situ en enfermedad metastásica.",
